mapper.select:
SELECT 
    museum_id AS id,
    title AS object_name,
    material AS cat1,
    dynasty AS cat2,
    type AS cat3,
    artist AS makers_name,
    image_url AS img_url
FROM artifact
WHERE museum = #{museum} 
  AND material REGEXP #{cat1} 
  AND dynasty = #{cat2} 
  AND type REGEXP #{cat3}

SELECT 
    museum_id AS id,
    title AS object_name,
    material AS cat1,
    dynasty AS cat2,
    type AS cat3,
    artist AS makers_name,
    image_url AS img_url
FROM artifact
WHERE 
    artist_bio REGEXP #{str} 
    OR material REGEXP #{str}
    OR title REGEXP #{str} 
    OR type REGEXP #{str} 
    OR provenance REGEXP #{str}
    OR period REGEXP #{str} 
    OR artist REGEXP #{str} 
LIMIT 400,100
